def _norm_map(text):
    idx, buf = [], []
    for i, ch in enumerate(text):
        for c in norm(ch):
            buf.append(c); idx.append(i)
    return ''.join(buf), idx

_nm = {}
def EX(key, start, end, fix=None, nth=0):
    path = sorted(glob.glob(os.path.join(HERE, F[key])))[0]
    text, _ = get(path)
    if path not in _nm: _nm[path] = _norm_map(text)
    nt, idx = _nm[path]
    pat = lambda s: re.escape(norm(s)).replace(r'\ ', r'\s*')
    ms = list(re.finditer(pat(start), nt))
    assert ms, f'start not found: {key} {start}'
    m = e = None
    for cand in ms[nth:]:
        ee = re.compile(pat(end)).search(nt, cand.start())
        if ee and ee.end() - cand.start() < 3000:
            m, e = cand, ee; break
    assert m, f'end not found: {key} {end}'
    s = text[idx[m.start()]: idx[e.end() - 1] + 1]
    s = re.sub(r'\((?:B|A) ?\d+[a-z]? Diels\)', '', s)
    s = re.sub(r'([Ͱ-Ͽἀ-῿])- +([Ͱ-Ͽἀ-῿])', r'\1\2', s)
    s = re.sub(r'\s+', ' ', s).strip()
    import unicodedata as _u
    s = _u.normalize('NFC', s)
    for a, b in (fix or {}).items():
        a = _u.normalize('NFC', a)
        assert a in s, f'fix target not in text: {key} {a!r}'
        s = s.replace(a, b)
    s = s.replace('‘‘', '').replace('’’', '').replace('“', '').replace('”', '').replace('"', '')
    s = re.sub(r'\s+', ' ', s).strip()
    return s

def CHECK(key, s):
    """verify that s occurs verbatim (accent-insensitively) in the source; return s"""
    EX(key, s, s.split()[-1] if len(s.split()) > 1 else s)
    return s

# --------------------------------------------------------------------------------------------
# Each quote: id -> (header, [greek paragraphs or verse lines], translation, note or None, verse?)
# --------------------------------------------------------------------------------------------
Q = {}
def add(i, head, greek, tr, note=None, verse=False):
    Q[i] = (head, greek if isinstance(greek, list) else [greek], tr, note, verse)

